contracts.body:
{
    new_transform("asinh", transform = asinh, inverse = sinh, d_transform = function(x) 1/sqrt(x^2 + 1), d_inverse = cosh)
}

{
    new_transform("asn", function(x) 2 * asin(sqrt(x)), function(x) sin(x/2)^2, d_transform = function(x) 1/sqrt(x - x^2), d_inverse = function(x) sin(x)/2, domain = c(0, 1))
}

{
    new_transform("atanh", "atanh", "tanh", d_transform = function(x) 1/(1 - x^2), d_inverse = function(x) 1/cosh(x)^2, domain = c(-1, 1))
}

{
    if (abs(p) < 1e-07) {
        trans <- function(x) log(x + offset)
        inv <- function(x) exp(x) - offset
        d_trans <- function(x) 1/(x + offset)
        d_inv <- "exp"
    }
    else {
        trans <- function(x) ((x + offset)^p - 1)/p
        inv <- function(x) (x * p + 1)^(1/p) - offset
        d_trans <- function(x) (x + offset)^(p - 1)
        d_inv <- function(x) (x * p + 1)^(1/p - 1)
    }
    trans_with_check <- function(x) {
        if (any((x + offset) < 0, na.rm = TRUE)) {
            cli::cli_abort(c("{.fun transform_boxcox} must be given only positive values", i = "Consider using {.fun transform_modulus} instead?"))
        }
        trans(x)
    }
    new_transform(paste0("pow-", format(p)), trans_with_check, inv, d_transform = d_trans, d_inverse = d_inv, domain = c(0, Inf))
}

{
    trans_list <- lapply(list2(...), as.transform)
    if (length(trans_list) == 0) {
        cli::cli_abort("{.fun transform_compose} must include at least 1 transformer to compose")
    }
    range <- trans_list[[1]]$transform(trans_list[[1]]$domain)
    for (trans in trans_list[-1]) {
        lower <- max(min(trans$domain), min(range))
        upper <- min(max(trans$domain), max(range))
        if (isTRUE(lower <= upper)) {
            range <- trans$transform(c(lower, upper))
        }
        else {
            range <- c(NA_real_, NA_real_)
            break
        }
    }
    domain <- compose_rev(range, trans_list)
    if (any(is.na(domain))) {
        cli::cli_abort("Sequence of transformations yields invalid domain")
    }
    domain <- range(domain)
    names <- vapply(trans_list, "[[", "name", FUN.VALUE = character(1))
    has_d_transform <- all(lengths(lapply(trans_list, "[[", "d_transform")) > 0)
    has_d_inverse <- all(lengths(lapply(trans_list, "[[", "d_inverse")) > 0)
    new_transform(paste0("composition(", paste0(names, collapse = ","), ")"), transform = function(x) compose_fwd(x, trans_list), inverse = function(x) compose_rev(x, trans_list), d_transform = if (has_d_transform) 
        function(x) compose_deriv_fwd(x, trans_list), d_inverse = if (has_d_inverse) 
        function(x) compose_deriv_rev(x, trans_list), breaks = function(x) trans_list[[1]]$breaks(x), domain = domain)
}

{
    new_transform("date", transform = "from_date", inverse = "to_date", breaks = breaks_pretty(), domain = to_date(c(-Inf, Inf)))
}

{
    force(base)
    new_transform(paste0("power-", format(base)), function(x) base^x, function(x) log(x, base = base), d_transform = function(x) base^x * log(base), d_inverse = function(x) 1/x/log(base))
}

{
    check_installed("hms", "for the 'hms' transformation.")
    new_transform("hms", transform = function(x) {
        structure(as.numeric(x), names = names(x))
    }, inverse = hms::as_hms, breaks = breaks_hms())
}

{
    new_transform("identity", "force", "force", d_transform = function(x) rep(1, length(x)), d_inverse = function(x) rep(1, length(x)))
}

{
    force(base)
    new_transform(paste0("log-", format(base)), function(x) log(x, base), function(x) base^x, d_transform = function(x) 1/x/log(base), d_inverse = function(x) base^x * log(base), breaks = log_breaks(base = base), domain = c(1e-100, Inf))
}

{
    transform_log(10)
}

{
    new_transform("log1p", "log1p", "expm1", d_transform = function(x) 1/(1 + x), d_inverse = "exp", domain = c(-1 + .Machine$double.eps, Inf))
}

{
    transform_log(2)
}

{
    if (abs(p) < 1e-07) {
        trans <- function(x) sign(x) * log(abs(x) + offset)
        inv <- function(x) sign(x) * (exp(abs(x)) - offset)
        d_trans <- function(x) 1/(abs(x) + offset)
        d_inv <- function(x) exp(abs(x))
    }
    else {
        trans <- function(x) sign(x) * ((abs(x) + offset)^p - 1)/p
        inv <- function(x) sign(x) * ((abs(x) * p + 1)^(1/p) - offset)
        d_trans <- function(x) (abs(x) + offset)^(p - 1)
        d_inv <- function(x) (abs(x) * p + 1)^(1/p - 1)
    }
    new_transform(paste0("mt-pow-", format(p)), trans, inv, d_transform = d_trans, d_inverse = d_inv)
}

{
    qfun <- match.fun(paste0("q", distribution))
    pfun <- match.fun(paste0("p", distribution))
    dfun <- match.fun(paste0("d", distribution))
    new_transform(paste0("prob-", distribution), function(x) qfun(x, ...), function(x) pfun(x, ...), d_transform = function(x) 1/dfun(qfun(x, ...), ...), d_inverse = function(x) dfun(x, ...), domain = c(0, 1))
}

{
    new_transform("pseudo_log", function(x) asinh(x/(2 * sigma))/log(base), function(x) 2 * sigma * sinh(x * log(base)), d_transform = function(x) 1/(sqrt(4 + x^2/sigma^2) * sigma * log(base)), d_inverse = function(x) 2 * sigma * cosh(x * log(base)) * log(base))
}

{
    new_transform("reciprocal", function(x) 1/x, function(x) 1/x, d_transform = function(x) -1/x^2, d_inverse = function(x) -1/x^2)
}

{
    new_transform("reverse", function(x) -x, function(x) -x, d_transform = function(x) rep(-1, length(x)), d_inverse = function(x) rep(-1, length(x)), minor_breaks = regular_minor_breaks(reverse = TRUE))
}

{
    new_transform("sqrt", "sqrt", function(x) ifelse(x < 0, NA_real_, x^2), d_transform = function(x) 0.5/sqrt(x), d_inverse = function(x) 2 * x, domain = c(0, Inf))
}

{
    force(tz)
    to_time <- function(x) {
        structure(x, class = c("POSIXct", "POSIXt"), tzone = tz)
    }
    from_time <- function(x) {
        if (!inherits(x, "POSIXct")) {
            cli::cli_abort("{.fun transform_time} works with objects of class {.cls POSIXct} only")
        }
        if (is.null(tz)) {
            tz <<- attr(as.POSIXlt(x), "tzone")[[1]]
        }
        structure(as.numeric(x), names = names(x))
    }
    new_transform("time", transform = "from_time", inverse = "to_time", breaks = breaks_pretty(), domain = to_time(c(-Inf, Inf)))
}

{
    unit <- arg_match(unit)
    new_transform("timespan", transform = function(x) {
        structure(as.numeric(as.difftime(x, units = unit), units = "secs"), names = names(x))
    }, inverse = function(x) {
        x <- as.difftime(x, units = "secs")
        units(x) <- unit
        x
    }, breaks = breaks_timespan(unit), format = label_timespan(unit))
}

{
    eps <- 1e-07
    if (abs(p) < eps) {
        trans_pos <- log1p
        inv_pos <- expm1
        d_trans_pos <- function(x) 1/(1 + x)
        d_inv_pos <- exp
    }
    else {
        trans_pos <- function(x) ((x + 1)^p - 1)/p
        inv_pos <- function(x) (p * x + 1)^(1/p) - 1
        d_trans_pos <- function(x) (x + 1)^(p - 1)
        d_inv_pos <- function(x) (p * x + 1)^(1/p - 1)
    }
    if (abs(2 - p) < eps) {
        trans_neg <- function(x) -log1p(-x)
        inv_neg <- function(x) 1 - exp(-x)
        d_trans_neg <- function(x) 1/(1 - x)
        d_inv_new <- function(x) exp(-x)
    }
    else {
        trans_neg <- function(x) -((-x + 1)^(2 - p) - 1)/(2 - p)
        inv_neg <- function(x) 1 - (-(2 - p) * x + 1)^(1/(2 - p))
        d_trans_neg <- function(x) (1 - x)^(1 - p)
        d_inv_neg <- function(x) (-(2 - p) * x + 1)^(1/(2 - p) - 1)
    }
    new_transform(paste0("yeo-johnson-", format(p)), function(x) trans_two_sided(x, trans_pos, trans_neg), function(x) trans_two_sided(x, inv_pos, inv_neg), d_transform = function(x) trans_two_sided(x, d_trans_pos, d_trans_neg, f_at_0 = 1), d_inverse = function(x) trans_two_sided(x, d_inv_pos, d_inv_neg, f_at_0 = 1))
}
